#include "Vr10_observer_core.h"
#include "verilated.h"
#include <fstream>
#include <iostream>
#include <cstdint>
static void cycle(Vr10_observer_core&t){t.clk=0;t.eval();t.clk=1;t.eval();}
int main(int argc,char**argv){VerilatedContext c;Vr10_observer_core t{&c};t.handoff_reblend=0;t.rst_n=0;cycle(t);t.rst_n=1;cycle(t);std::ifstream f(argv[1]);int permission,prediction_previous,brake,automatic,hold,fallback,reset,theta,phi,prev,cap,ref,refv,u,ready,fault;int n=0,maxcy=0;while(f>>permission>>prediction_previous>>brake>>automatic>>hold>>fallback>>reset>>theta>>phi>>prev>>cap>>ref>>refv>>u>>ready>>fault){if(reset){t.clear=1;cycle(t);t.clear=0;cycle(t);}t.motion_assist_permission=permission;t.prediction_duty=prediction_previous;t.automatic_brake=brake;t.automatic_policy=automatic;t.automatic_hold=hold;t.fallback_duty=fallback;t.theta=theta;t.phi=phi;t.reference_offset=ref;t.reference_velocity=refv;t.previous_duty=prev;t.limit_permille=cap;t.start=1;cycle(t);t.start=0;int cy=0;while(!t.done&&cy<500){t.motion_assist_permission=!permission;t.prediction_duty=123456;t.reference_offset=0x7fffffff;t.theta=0x7fffffff;t.phi=0x80000000;t.previous_duty=123456;t.limit_permille=0;cycle(t);cy++;}int32_t expected_z[7];int expected_samples,ei,el,ea;for(int j=0;j<7;j++)f>>expected_z[j];f>>expected_samples>>ei>>el>>ea;if(int32_t(t.debug_integral)!=ei||int32_t(t.debug_lp)!=el||t.debug_age!=ea){std::cerr<<"integrator mismatch "<<n<<" I="<<int32_t(t.debug_integral)<<"/"<<ei<<" LP="<<int32_t(t.debug_lp)<<"/"<<el<<" age="<<int(t.debug_age)<<"/"<<ea<<"\n";return 7;}for(int j=0;j<7;j++)if(int32_t(t.debug_state[j])!=expected_z[j]){std::cerr<<"state mismatch "<<n<<" index "<<j<<"\n";return 4;}if(t.debug_samples!=expected_samples)return 5;if(cy>maxcy)maxcy=cy;if(cy==500||int32_t(t.duty)!=u||t.ready!=ready||t.fault!=fault){std::cerr<<"mismatch "<<n<<" "<<int32_t(t.duty)<<" != "<<u<<" ready "<<int(t.ready)<<" "<<ready<<" fault "<<int(t.fault)<<" "<<fault<<" cy "<<cy<<"\n";return 1;}cycle(t);n++;}
// Every busy clock can be aborted; no stale result/command is allowed.
for(int stop=0;stop<=maxcy;stop++){t.clear=1;cycle(t);t.clear=0;t.automatic_policy=1;t.automatic_hold=1;t.automatic_brake=1;t.motion_assist_permission=1;t.prediction_duty=-70;t.reference_velocity=0;t.fallback_duty=0;t.theta=10;t.phi=-20;t.reference_offset=0;t.previous_duty=0;t.limit_permille=150;t.start=1;cycle(t);t.start=0;for(int j=0;j<stop;j++)cycle(t);t.clear=1;cycle(t);if(t.busy||t.done||t.duty||t.fault||t.ready)return 2;t.clear=0;for(int j=0;j<maxcy+4;j++){cycle(t);if(t.done||t.duty)return 3;}}
std::cout<<"PASS transactions="<<n<<" maxcycles="<<maxcy<<" every_cycle_clear="<<maxcy+1<<"\n";}
